installer-gui-script.script:
function oxoCheckOS() {
    if (system.compareVersions(system.version.ProductVersion, '14.0') < 0) {
        my.result.type = 'Fatal';
        my.result.title = 'macOS 14 or Later Required';
        my.result.message = '__PRODUCT__ requires macOS 14 (Sonoma) or later. '
            + 'This Mac runs macOS ' + system.version.ProductVersion + '.';
        return false;
    }
    return true;
}
